import Link from 'next/link';

const collections = [
  ['manuscripts', 'Manuscripts & Letters'],
  ['photographs', 'Photographs'],
  ['videos', 'Videos'],
];

export default function CollectionNavigation({compact=false,current=''}:{compact?:boolean;current?:string}) {
  return <nav className="collection-navigation" aria-label="Archive collections">
    {!compact&&<Link href="/archive" aria-current={!current?'page':undefined}>All archive records</Link>}
    {collections.map(([key,title])=><Link key={key} href={`/archive?collection=${key}`} aria-current={current===key?'page':undefined}>{title}</Link>)}
  </nav>;
}
